import{_ as r,C as s,o as a,c as l,j as d,a as t,b as c,w as o,E,a3 as n,a2 as h}from"./chunks/framework.CWWEQfK7.js";const _=JSON.parse('{"title":"定位分析与检索问题","description":"按进程、依赖、队列、新鲜度和证据层级定位分析、检索与 MCP 问题。","frontmatter":{"page_id":"guide-debugging","description":"按进程、依赖、队列、新鲜度和证据层级定位分析、检索与 MCP 问题。"},"headers":[],"relativePath":"guide/debugging.md","filePath":"guide/debugging.md","lastUpdated":1786289447000}'),p={name:"guide/debugging.md"};function A(u,e,B,k,C,b){const i=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=d("h1",{id:"定位分析与检索问题",tabindex:"-1"},[t("定位分析与检索问题 "),d("a",{class:"header-anchor",href:"#定位分析与检索问题","aria-label":'Permalink to "定位分析与检索问题"'},"​")],-1)),e[2]||(e[2]=d("p",null,"排查 Ershu 时，先区分“进程活着”“依赖可用”“任务完成”和“结果足够新”这四件事。它们有不同的检查入口，不能只凭一个绿色健康页判断整个系统正常。",-1)),e[3]||(e[3]=d("h2",{id:"先用最短路径定位层级",tabindex:"-1"},[t("先用最短路径定位层级 "),d("a",{class:"header-anchor",href:"#先用最短路径定位层级","aria-label":'Permalink to "先用最短路径定位层级"'},"​")],-1)),(a(),c(n,null,{default:o(()=>[E(i,{id:"mermaid-9",class:"ershu-mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%A1%B5%E9%9D%A2%E6%88%96%E5%B7%A5%E5%85%B7%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20B%7B%22API%20%E6%88%96%20MCP%20%E5%AD%98%E6%B4%BB%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20C%5B%22%E6%A3%80%E6%9F%A5%E8%BF%9B%E7%A8%8B%E5%90%AF%E5%8A%A8%E6%97%A5%E5%BF%97%E5%92%8C%E7%8E%AF%E5%A2%83%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22API%20%E4%BE%9D%E8%B5%96%E6%A3%80%E6%9F%A5%E9%80%9A%E8%BF%87%E5%90%97%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E6%A3%80%E6%9F%A5%20PostgreSQL%20%E6%88%96%20Milvus%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20F%7B%22%E4%BB%BB%E5%8A%A1%E5%9C%A8%E6%8E%A8%E8%BF%9B%E5%90%97%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20G%5B%22%E6%A3%80%E6%9F%A5%20Worker%E3%80%81%E9%98%9F%E5%88%97%E5%92%8C%E8%BF%90%E8%A1%8C%E9%94%99%E8%AF%AF%22%5D%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20H%7B%22%E7%BB%93%E6%9E%9C%E5%BD%93%E5%89%8D%E4%B8%94%E5%AE%8C%E6%95%B4%E5%90%97%EF%BC%9F%22%7D%0A%20%20H%20--%3E%7C%22%E5%90%A6%22%7C%20I%5B%22%E6%A3%80%E6%9F%A5%E6%8F%90%E4%BA%A4%E3%80%81%E6%96%B0%E9%B2%9C%E5%BA%A6%E3%80%81%E9%99%8D%E7%BA%A7%E4%B8%8E%E6%88%AA%E6%96%AD%22%5D%0A%20%20H%20--%3E%7C%22%E6%98%AF%22%7C%20J%5B%22%E6%8C%89%E6%9D%83%E9%99%90%E3%80%81%E6%9F%A5%E8%AF%A2%E8%8C%83%E5%9B%B4%E5%92%8C%E8%AF%81%E6%8D%AE%E5%B1%82%E7%BA%A7%E7%BB%A7%E7%BB%AD%E5%AE%9A%E4%BD%8D%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=h(`<h2 id="第-1-层-确认进程-而不是整个系统" tabindex="-1">第 1 层：确认进程，而不是整个系统 <a class="header-anchor" href="#第-1-层-确认进程-而不是整个系统" aria-label="Permalink to &quot;第 1 层：确认进程，而不是整个系统&quot;">​</a></h2><p>下面是建议检查命令，本任务没有在你的部署中执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/api/v1/health/dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8001/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>检查</th><th>能证明什么</th><th>不能证明什么</th></tr></thead><tbody><tr><td>API <code>/health</code></td><td>API 进程能响应 HTTP</td><td>数据库、Milvus、Redis、Worker 和模型通道可用</td></tr><tr><td>API <code>/api/v1/health/dependencies</code></td><td>PostgreSQL 与 Milvus 各自的探测结果</td><td>Redis、Worker、模型通道和仓库凭据可用</td></tr><tr><td>MCP <code>/health</code></td><td>MCP 进程能响应 HTTP</td><td>数据库、认证、项目权限或 27 个工具可用</td></tr><tr><td>MCP <code>get_server_info</code></td><td>凭据可用，协议调用成功，并返回当前工具和构建身份</td><td>某个项目的索引一定完整</td></tr><tr><td>Worker 进程持续运行</td><td>启动校验和结构化解析器自检通过</td><td>一定能完成某个具体任务</td></tr></tbody></table><p>Worker 没有 HTTP 健康端点。它启动时会验证 <code>ENCRYPTION_KEY</code>、分析注册表、数据库连接和结构化解析器；其中任何一项失败都可能让进程退出。最终仍要用一条实际排队任务能否推进来验证。</p><h2 id="第-2-层-任务排队但不动" tabindex="-1">第 2 层：任务排队但不动 <a class="header-anchor" href="#第-2-层-任务排队但不动" aria-label="Permalink to &quot;第 2 层：任务排队但不动&quot;">​</a></h2><p>先打开运行详情，记录运行编号、当前状态、最后事件和错误，不要立刻重建索引。</p><table tabindex="0"><thead><tr><th>现象</th><th>可能的边界</th><th>可观察的下一步</th></tr></thead><tbody><tr><td>一直停在排队</td><td>Worker 没运行、连错数据库，或无法领取任务</td><td>确认 Worker 与 API 使用同一 <code>DATABASE_URL</code>；Worker 日志应出现启动和轮询信息</td></tr><tr><td>运行后很快失败</td><td>密钥、仓库凭据、模型通道、解析器或外部依赖失败</td><td>查看运行错误和 Worker 同期日志；错误应指向失败阶段</td></tr><tr><td>等待用户输入</td><td>已开启分析提问，且任务正在等待回答</td><td>在运行页面回答问题，或等待配置的超时处理</td></tr><tr><td>完成但带警告</td><td>文档已发布，但搜索索引等后续步骤降级</td><td>查看警告与各层状态，不要把“完成”理解为所有索引都完整</td></tr><tr><td>定时检查没有产生任务</td><td>Poller 没单独运行、Cron 未到期、Redis 租约未取得，或提交已是当前状态</td><td>查看最近轮询时间与 <code>repository.poll_scheduled</code> 审计记录</td></tr></tbody></table><p>队列租约超时默认 <code>600</code> 秒。Worker 会恢复失去有效租约的中断任务，但不要靠缩短租约掩盖一个持续崩溃的 Worker。</p><h2 id="第-3-层-仓库无法准备" tabindex="-1">第 3 层：仓库无法准备 <a class="header-anchor" href="#第-3-层-仓库无法准备" aria-label="Permalink to &quot;第 3 层：仓库无法准备&quot;">​</a></h2><p>远程仓库先检查登记的 URL、默认分支和凭据。私有仓库可以使用仓库自身保存的凭据，也可以按仓库类型使用 <code>GITHUB_TOKEN</code> 或 <code>GITLAB_TOKEN</code>。Git 命令默认最多运行 <code>120</code> 秒。</p><p>本地仓库还要同时满足：</p><ul><li>路径位于运行进程能访问的文件系统；</li><li>路径落在 <code>TRUSTED_LOCAL_PATHS</code> 内；</li><li>生产环境没有启用开发用宽松开关；</li><li>如果由 Worker 分析、由 MCP 读取，两台主机都能看到登记的路径。</li></ul><p>轮询遇到未提交修改会返回 <code>local_workspace_dirty</code>，没有 Git 提交会返回 <code>repository_has_no_git_commit</code>。这些是有意的跳过，不是队列故障。</p><h2 id="第-4-层-搜索结果为空或降级" tabindex="-1">第 4 层：搜索结果为空或降级 <a class="header-anchor" href="#第-4-层-搜索结果为空或降级" aria-label="Permalink to &quot;第 4 层：搜索结果为空或降级&quot;">​</a></h2><p>先查看响应中的 <code>mode</code>、<code>degraded</code>、<code>degradation_reason</code>、<code>retrieval_sources</code> 和 <code>fallback_used</code>。</p><ul><li><code>keyword</code> 只走词法结果。</li><li><code>semantic</code> 只接受语义结果。没有嵌入通道、可用索引或 Milvus 查询时，它会明确失败，不会把词法结果伪装成语义命中。</li><li><code>hybrid</code> 组合语义与词法结果。语义分支不可用时，它可以返回词法结果，但会把降级和回退写进响应。</li></ul><p>再查看仓库或运行结果中的 <code>search_index_status</code>。<code>indexing</code> 表示后台索引仍在进行；仓库的 <code>keyword_only</code>、<code>degraded</code>，以及运行结果的 <code>degraded</code>、<code>unavailable</code>，都表示不能把结果当作完整语义检索。后台搜索索引开启时，分析任务可能先完成，索引稍后才完成。</p><p>如果只有文档命中，响应可能标记 <code>documents_fallback</code>。这类结果适合导航，不是实现证据，应继续用源码读取核对。</p><h2 id="第-5-层-关系或变更面看起来不完整" tabindex="-1">第 5 层：关系或变更面看起来不完整 <a class="header-anchor" href="#第-5-层-关系或变更面看起来不完整" aria-label="Permalink to &quot;第 5 层：关系或变更面看起来不完整&quot;">​</a></h2><p>关系查询和变更面查询都受范围限制。检查：</p><ul><li><code>data_status</code> 是 <code>available</code>、<code>partial</code>、<code>stale</code> 还是 <code>unavailable</code>；</li><li><code>result_status</code> 是否因为数据不可用而无法判断；</li><li>仓库覆盖范围、未命中仓库、查询 <code>limit</code> 和截断标记；</li><li>结果是 <code>direct</code> 还是 <code>related</code>，以及置信度；</li><li>仓库最近观察到的提交是否与索引提交一致。</li></ul><p>“没有返回”不总等于“没有关系”。数据不可用时，正确结论是未知；结果被截断时，正确结论是当前返回了一组有界候选。</p><h2 id="第-6-层-文档与源码冲突" tabindex="-1">第 6 层：文档与源码冲突 <a class="header-anchor" href="#第-6-层-文档与源码冲突" aria-label="Permalink to &quot;第 6 层：文档与源码冲突&quot;">​</a></h2><p>按以下顺序判断：</p><ol><li>查看文档对应的分支、提交和新鲜度。</li><li>查看 <code>authority</code>。AI 生成文档属于 <code>secondary</code>，源码和结构化契约属于 <code>source_derived</code>。</li><li>用目录和代码索引定位路径。</li><li>用 <code>read_code_context</code> 或当前本地源码核对精确字段、默认值和行为。</li></ol><p>源码与文档冲突时，以当前源码为准。<code>refresh_repository_facts</code> 只刷新四类事实，不会修正文档，因此不要把一次事实刷新误当作文档已经重写。</p><h2 id="带着证据报告问题" tabindex="-1">带着证据报告问题 <a class="header-anchor" href="#带着证据报告问题" aria-label="Permalink to &quot;带着证据报告问题&quot;">​</a></h2><p>一份可复现的问题记录至少包含：</p><ul><li>模块和运行入口；</li><li>项目、仓库和运行编号，但不包含密钥；</li><li>仓库分支、提交和新鲜度；</li><li>第一个失败状态或错误类别；</li><li>API 依赖检查中数据库与 Milvus 的结果；</li><li>Worker、API 或 MCP 同一时间段的相关日志；</li><li>查询模式、降级、回退、覆盖范围和截断信息；</li><li>能稳定重现的最短步骤。</li></ul><p>不要附上 <code>SECRET_KEY</code>、<code>ENCRYPTION_KEY</code>、<code>MCP_KEY_PEPPER</code>、MCP 密钥、Webhook 密钥或仓库访问凭据。</p><blockquote><p>主要源码位置：<code>api/src/ershu/api/routes/health.py</code>、<code>worker/src/ershu/workers/analysis.py</code>、<code>core/src/ershu/services/retrieval.py</code>、<code>core/src/ershu/services/repositories/freshness.py</code>、<code>mcp/src/ershu/mcp/tool_runtime.py</code>。</p></blockquote>`,32))])}const g=r(p,[["render",A]]);export{_ as __pageData,g as default};
